import{_ as r,C as n,c as s,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Operations","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/advanced-configuration/operations.md","filePath":"master/supply-chain/manufacturing/advanced-configuration/operations.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/manufacturing/advanced-configuration/operations.md"};function d(p,e,u,g,c,h){const a=n("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h1><p>An operation is one step in making a product, such as assembling or testing. Each operation belongs to a bill of materials and runs at a work center. When you confirm a manufacturing order, Aureus turns every operation into a work order.</p><blockquote><p><strong>In simple words:</strong> An operation is a named step with a place and a time.</p></blockquote><p>Open <code>Manufacturing → Configurations → Operations</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Gate</p><p><strong>Operations</strong> is hidden until <strong>Work Orders</strong> is on in <code>Manufacturing → Settings → Manage Operations</code>. Ordering steps needs <strong>Work Order Dependencies</strong> as well. See <a href="./work-order-dependencies.html">Work order dependencies</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',7)),o(a,{src:"/images1/manufacturing/op_list.png",alt:"Operations list with Assemble Components and Test & Pack, tab All, all columns visible"}),e[1]||(e[1]=t('<ul><li><strong>Tabs:</strong> <strong>All</strong> and <strong>Archived</strong>.</li><li><strong>Columns:</strong> <strong>Operation</strong>, <strong>Bill of Material</strong>, <strong>Work Center</strong>, <strong>Duration Computation</strong>, <strong>Default Duration</strong>, <strong>Worksheet</strong>.</li><li><strong>New Operation:</strong> opens the create form.</li></ul><h2 id="create-an-operation" tabindex="-1">Create an operation <a class="header-anchor" href="#create-an-operation" aria-label="Permalink to &quot;Create an operation&quot;">​</a></h2><p>Scenario: add <strong>Test &amp; Pack</strong> to <strong>BOM-MC-LAPTOP</strong>. It runs at <strong>Quality &amp; Packing</strong> and takes 30 minutes.</p><ol><li>Open <code>Manufacturing → Configurations → Operations</code> and click <strong>New Operation</strong>.</li></ol>',4)),o(a,{src:"/images1/manufacturing/op_create_general.png",alt:"Create Operation form, General box filled: Operation Test & Pack, Bill of Material BOM-MC-LAPTOP, Work Center Quality & Packing"}),e[2]||(e[2]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Operation:</em></strong> The step name. Required.</li><li><strong><em>Bill of Material:</em></strong> The BoM this step belongs to. Required.</li><li><strong><em>Work Center:</em></strong> Where the step runs. Required. You can create a new work center from this field.</li><li><strong><em>Apply on Variants:</em></strong> Limit the step to chosen variant values of the BoM product. Leave it empty to use the step for every variant. See <a href="./bom-variants.html">BoM variants</a>.</li><li><strong><em>Company:</em></strong> Shown from the BoM. You cannot change it here.</li></ul><h3 id="work-sheet" tabindex="-1">Work Sheet <a class="header-anchor" href="#work-sheet" aria-label="Permalink to &quot;Work Sheet&quot;">​</a></h3><p>A worksheet holds the instructions for the person doing the step.</p>',4)),o(a,{src:"/images1/manufacturing/op_create_worksheet.png",alt:"Work Sheet box with Text selected and a short description of the test steps"}),e[3]||(e[3]=t('<ul><li><strong><em>Worksheet:</em></strong> Choose a type. Required. The default is <strong>Text</strong>. <ul><li><strong>PDF:</strong> A <strong>PDF</strong> upload field appears. Upload the instruction file.</li><li><strong>Google Slide:</strong> A <strong>Google Slide</strong> link field appears. Paste the URL.</li><li><strong>Text:</strong> A <strong>Description</strong> box appears. Type the instructions.</li></ul></li></ul><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3>',2)),o(a,{src:"/images1/manufacturing/op_create_settings.png",alt:"Settings box with Duration Computation Set duration manually and Default Duration 30:00"}),e[4]||(e[4]=t(`<ul><li><strong><em>Duration Computation:</em></strong> How Aureus finds the time for one cycle. Required. <ul><li><strong>Set duration manually:</strong> Aureus always uses <strong>Default Duration</strong>.</li><li><strong>Compute based on tracked time:</strong> Aureus averages the real time of recent finished work orders. A <strong>Based on last ... work orders</strong> field appears. The default is 10. If no work orders are finished yet, it uses <strong>Default Duration</strong>.</li></ul></li><li><strong><em>Default Duration:</em></strong> Minutes for one cycle, shown as hours and minutes. The default is 60:00.</li></ul><ol start="2"><li>Click <strong>Create</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with <strong>Set duration manually</strong>. Switch to tracked time after a few work orders are finished.</p></div><h2 id="add-steps-from-the-bom" tabindex="-1">Add steps from the BoM <a class="header-anchor" href="#add-steps-from-the-bom" aria-label="Permalink to &quot;Add steps from the BoM&quot;">​</a></h2><p>You can also add steps on the <strong>Operations</strong> tab of the BoM. It lists each step with its work center and duration. The tab has <strong>Edit Operation</strong>, <strong>Copy Existing Operations</strong> and <strong>Add a line</strong>. See <a href="./../basic-setup/bill-of-materials.html">Bill of materials</a>.</p><h2 id="what-a-step-becomes" tabindex="-1">What a step becomes <a class="header-anchor" href="#what-a-step-becomes" aria-label="Permalink to &quot;What a step becomes&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Operation &quot;Assemble Components&quot;  -&gt;  work order on Assembly Station</span></span>
<span class="line"><span>Operation &quot;Test &amp; Pack&quot;          -&gt;  work order on Quality &amp; Packing</span></span></code></pre></div><p>The work order copies the work center and the expected duration. It uses the capacity and efficiency of the work center. See <a href="./work-centers.html">Work centers</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>View</strong> and <strong>Edit</strong> show or change the step.</li><li><strong>Delete</strong> archives it. Archived steps are listed on the <strong>Archived</strong> tab and are no longer used on new orders.</li><li>Work orders already created keep their own data.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./work-centers.html">Work centers</a></li><li><a href="./work-order-dependencies.html">Work order dependencies</a></li><li><a href="./../workflows/work-orders.html">Work orders</a></li><li><a href="./../basic-setup/bill-of-materials.html">Bill of materials</a></li></ul>`,12))])}const k=r(l,[["render",d]]);export{f as __pageData,k as default};
